scss.scss_field:
background: inherit;
color: inherit;
.layout-region{
  &.subtitle {
    margin-bottom: $wbu-margin;
  }
  &.title{
    margin-bottom: $wbu-margin*1.5;
  }
}
.content-text {
  &.space-padding{
    overflow: visible;
  }
  padding-right:$wbu-margin;
  @include media-min(MD){
    min-height: auto;
  }    
  >  div {
    max-width: 450px;
  }
}  

.content-image{
  overflow: visible;
   img {
     max-width: 100%;
     min-height: 100%;
     object-fit: cover;
     @include media-min(MD){
       max-width: 1000px;
     }
}
}

